protected boolean isValidAccountHeldType(CredManAccountHeldType _credManAccountHeldType)
{


    // Call base logic
    boolean isValid = next isValidAccountHeldType(_credManAccountHeldType);

    // Add  additional valid enum value
    if (!isValid)
    {
        isValid = (_credManAccountHeldType == CredManAccountHeldType::METSalesinvoice);
    }

    return isValid;
}
